-- Phase 3 attack tests (36). DEV project only. Ends with an intentional exception so everything rolls back; the message is the report.
-- Not covered: truly parallel sessions (single-connection harness). Protection is by design: FOR UPDATE row locks + unique constraints.
create function pg_temp.r(name text, ok boolean) returns text language sql as $$ select name || ': ' || case when coalesce(ok,false) then 'PASS' else 'FAIL' end || E'\n' $$;
create function pg_temp.u(x uuid) returns void language plpgsql as $$ begin perform set_config('request.jwt.claims', json_build_object('sub', x, 'role', 'authenticated')::text, true); execute 'set local role authenticated'; end $$;
create function pg_temp.su() returns void language plpgsql as $$ begin execute 'reset role'; end $$;
do $$
declare
  O uuid := gen_random_uuid(); S1 uuid := gen_random_uuid(); S2 uuid := gen_random_uuid(); S3 uuid := gen_random_uuid();
  O2 uuid := gen_random_uuid(); S4 uuid := gen_random_uuid(); A uuid := gen_random_uuid(); B uuid := gen_random_uuid(); C uuid := gen_random_uuid();
  M1 uuid; M2 uuid; P1 uuid; P2 uuid; P3 uuid; R1 uuid; R2 uuid; R3 uuid; cA uuid; cA2 uuid; cC uuid;
  v jsonb; res text := ''; code1 text; code2 text; code3 text; code4 text; h1 text; n int; i int; got_rl boolean := false; rc text; rb text; ra text;
begin
  insert into auth.users(id,aud,role,email,created_at,updated_at)
    select id,'authenticated','authenticated',nm||'@t.local',now(),now() from (values (O,'o'),(S1,'s1'),(S2,'s2'),(S3,'s3'),(O2,'o2'),(S4,'s4'),(A,'a'),(B,'b'),(C,'c')) t(id,nm);
  update auth.users set phone='+967700000001', phone_confirmed_at=now() where id=A;
  update auth.users set phone='+967700000003', phone_confirmed_at=now() where id=C;
  update auth.users set phone='+967700000002' where id=B;
  insert into public.merchants(owner_id,name,status,is_test) values (O,'M1','approved',true) returning id into M1;
  insert into public.merchants(owner_id,name,status,is_test) values (O2,'M2','approved',true) returning id into M2;
  insert into public.merchant_staff(merchant_id,user_id,permissions) values (M1,S1,'{issue_earn}'),(M1,S2,'{confirm_redeem}'),(M1,S3,'{}'),(M2,S4,'{issue_earn,confirm_redeem}');
  insert into public.programs(merchant_id,type,name,rules,status) values (M1,'stamps','P1','{"target":3}','active') returning id into P1;
  insert into public.programs(merchant_id,type,name,rules,status) values (M1,'points','P2','{}','active') returning id into P2;
  insert into public.programs(merchant_id,type,name,rules,status) values (M2,'stamps','P3','{"target":3}','active') returning id into P3;
  insert into public.rewards(program_id,merchant_id,title,cost) values (P1,M1,'R1',3) returning id into R1;
  insert into public.rewards(program_id,merchant_id,title,cost) values (P1,M1,'R2',3) returning id into R2;
  insert into public.rewards(program_id,merchant_id,title,cost) values (P2,M1,'R3',100) returning id into R3;
  perform pg_temp.u(A); v := public.issue_earn_code(P1);
  res := res || pg_temp.r('E01 a customer cannot issue codes', v->>'error'='forbidden');
  perform pg_temp.u(S3); v := public.issue_earn_code(P1);
  res := res || pg_temp.r('E02 staff without the permission cannot issue', v->>'error'='forbidden');
  perform pg_temp.u(S1); v := public.issue_earn_code(P1); code1 := v->>'code';
  res := res || pg_temp.r('E03 permitted staff issues a code in the agreed format', (v->>'ok')::boolean and code1 ~ '^[A-Z2-9]{4}-[A-Z2-9]{4}$' and (v->>'amount')::int=1);
  perform pg_temp.su(); h1 := private.hash_code(code1);
  res := res || pg_temp.r('E04 only a hash is stored, never the code', (select count(*) from public.reward_tokens where token_hash=code1 or token_hash=replace(code1,'-',''))=0 and (select count(*) from public.reward_tokens where token_hash=h1)=1);
  perform pg_temp.u(O); v := public.issue_earn_code(P1); code2 := v->>'code';
  res := res || pg_temp.r('E05 the owner can issue', (v->>'ok')::boolean);
  perform pg_temp.u(S1); v := public.issue_earn_code(P1, 99);
  res := res || pg_temp.r('E06 amounts above the cap are refused', v->>'error'='invalid_amount');
  perform pg_temp.u(S4); v := public.issue_earn_code(P1);
  res := res || pg_temp.r('E07 staff of another store cannot issue for this program', v->>'error'='forbidden');
  perform pg_temp.u(B); v := public.claim_earn_code(code1);
  res := res || pg_temp.r('C01 unverified phone cannot claim', v->>'error'='phone_not_verified');
  perform pg_temp.u(A); v := public.claim_earn_code(code1); perform pg_temp.su();
  res := res || pg_temp.r('C02 not joined: refused and the code is NOT consumed', v->>'error'='not_joined' and (select status from public.reward_tokens where token_hash=h1)='active');
  perform pg_temp.u(A); cA := public.join_program(P1); v := public.claim_earn_code(lower(replace(code1,'-',' ')));
  res := res || pg_temp.r('C03 claim adds exactly one stamp (input normalised)', (v->>'ok')::boolean and (v->>'balance')::int=1);
  v := public.claim_earn_code(code1); perform pg_temp.su();
  res := res || pg_temp.r('C04 replay returns the original result, no second stamp', (v->>'ok')::boolean and (v->>'replay')::boolean and (select stamps from public.cards where id=cA)=1 and (select count(*) from public.transactions where card_id=cA and type='earn')=1);
  perform pg_temp.u(C); cC := public.join_program(P1); v := public.claim_earn_code(code1); perform pg_temp.su();
  res := res || pg_temp.r('C05 a used code cannot be claimed by someone else', v->>'error'='code_used' and (select stamps from public.cards where id=cC)=0);
  update public.reward_tokens set expires_at = now() - interval '1 second' where token_hash=private.hash_code(code2);
  perform pg_temp.u(A); v := public.claim_earn_code(code2); perform pg_temp.su();
  res := res || pg_temp.r('C06 expired code refused, balance unchanged', v->>'error'='code_expired' and (select stamps from public.cards where id=cA)=1);
  perform pg_temp.u(O2); v := public.issue_earn_code(P3); code4 := v->>'code';
  perform pg_temp.u(C); v := public.claim_earn_code(code4); perform pg_temp.su();
  res := res || pg_temp.r('C07 another store''s code never credits this store''s card', v->>'error'='not_joined' and (select stamps from public.cards where id=cC)=0);
  perform pg_temp.u(O); v := public.issue_earn_code(P2, 40); code3 := v->>'code';
  perform pg_temp.u(A); cA2 := public.join_program(P2); v := public.claim_earn_code(code3); perform pg_temp.su();
  res := res || pg_temp.r('C08 points program credits the points amount', (v->>'ok')::boolean and (v->>'type')='points' and (select points from public.cards where id=cA2)=40);
  perform pg_temp.u(S1); v := public.issue_earn_code(P1); code3 := v->>'code';
  perform pg_temp.u(A);
  for i in 1..10 loop v := public.claim_earn_code('ZZZZ-ZZZ' || i); end loop;
  v := public.claim_earn_code(code3); perform pg_temp.su();
  res := res || pg_temp.r('B01 repeated wrong guesses lock claiming (even a valid code)', v->>'error'='too_many_attempts' and (select stamps from public.cards where id=cA)=1);
  perform pg_temp.u(S1);
  for i in 1..14 loop v := public.issue_earn_code(P1); if v->>'error'='rate_limited' then got_rl := true; end if; end loop; perform pg_temp.su();
  res := res || pg_temp.r('B02 issuing is rate limited per staff member', got_rl);
  update public.cards set stamps=3 where id=cA;
  perform pg_temp.u(C); v := public.request_redeem(cC, R1);
  res := res || pg_temp.r('R01 insufficient balance cannot request', v->>'error'='insufficient_balance');
  perform pg_temp.u(B); v := public.request_redeem(cA, R1);
  res := res || pg_temp.r('R02 unverified phone cannot request', v->>'error'='phone_not_verified');
  perform pg_temp.u(C); v := public.request_redeem(cA, R1);
  res := res || pg_temp.r('R03 cannot request against someone else''s card', v->>'error'='not_found');
  perform pg_temp.u(A); v := public.request_redeem(cA, R1); ra := v->>'code'; perform pg_temp.su();
  res := res || pg_temp.r('R04 request issues a code and deducts nothing', (v->>'ok')::boolean and (select stamps from public.cards where id=cA)=3);
  perform pg_temp.u(A); v := public.request_redeem(cA, R1); rb := v->>'code'; perform pg_temp.u(S2); v := public.confirm_redeem(ra);
  res := res || pg_temp.r('R05 a new request cancels the previous code', v->>'error'='code_unavailable');
  perform pg_temp.u(S4); v := public.confirm_redeem(rb);
  res := res || pg_temp.r('R06 another store''s staff cannot confirm', v->>'error'='wrong_store');
  perform pg_temp.u(S3); v := public.confirm_redeem(rb);
  res := res || pg_temp.r('R07 staff without the permission cannot confirm', v->>'error'='wrong_store');
  perform pg_temp.u(A); v := public.confirm_redeem(rb);
  res := res || pg_temp.r('R08 the customer cannot confirm their own redemption', v->>'error'='wrong_store');
  perform pg_temp.u(S2); v := public.confirm_redeem(rb); perform pg_temp.su();
  res := res || pg_temp.r('R09 authorised staff confirms: deducts and records the ledger', (v->>'ok')::boolean and (v->>'deducted')::int=3 and (select stamps from public.cards where id=cA)=0 and (select amount from public.transactions where card_id=cA and type='redeem')=-3 and (select created_by from public.transactions where card_id=cA and type='redeem')=S2);
  perform pg_temp.u(S2); v := public.confirm_redeem(rb); perform pg_temp.su();
  res := res || pg_temp.r('R10 confirming twice replays, never deducts twice', (v->>'replay')::boolean and (select stamps from public.cards where id=cA)=0 and (select count(*) from public.transactions where card_id=cA and type='redeem')=1);
  perform pg_temp.u(O); v := public.confirm_redeem(rb);
  res := res || pg_temp.r('R11 a used code cannot be confirmed by another staff member', v->>'error'='code_used');
  perform pg_temp.su(); update public.cards set stamps=3 where id=cA;
  perform pg_temp.u(A); v := public.request_redeem(cA, R1); rc := v->>'code'; perform pg_temp.su();
  update public.reward_tokens set expires_at = now() - interval '1 second' where token_hash=private.hash_code(rc);
  perform pg_temp.u(S2); v := public.confirm_redeem(rc); perform pg_temp.su();
  res := res || pg_temp.r('R12 expired redeem code refused, balance unchanged', v->>'error'='code_expired' and (select stamps from public.cards where id=cA)=3);
  perform pg_temp.u(A); v := public.request_redeem(cA, R1); ra := v->>'code'; v := public.request_redeem(cA, R2); rb := v->>'code';
  perform pg_temp.u(S2); v := public.confirm_redeem(ra);
  res := res || pg_temp.r('R13a double-spend: first confirm succeeds', (v->>'ok')::boolean);
  v := public.confirm_redeem(rb); perform pg_temp.su();
  res := res || pg_temp.r('R13b double-spend: second confirm refused, balance never negative', v->>'error'='insufficient_balance' and (select stamps from public.cards where id=cA)=0);
  perform pg_temp.u(A);
  begin perform 1 from public.reward_tokens; res := res || pg_temp.r('X01 customers cannot read reward_tokens', false);
  exception when insufficient_privilege then res := res || pg_temp.r('X01 customers cannot read reward_tokens', true); end;
  perform pg_temp.su(); execute 'set local role anon';
  begin perform public.claim_earn_code('AAAA-AAAA'); res := res || pg_temp.r('X02 anonymous users cannot call the functions', false);
  exception when insufficient_privilege then res := res || pg_temp.r('X02 anonymous users cannot call the functions', true); end;
  perform pg_temp.su();
  begin insert into public.merchant_staff(merchant_id,user_id,permissions) values (M1,B,'{superadmin}'); res := res || pg_temp.r('X03 unknown permissions are rejected', false);
  exception when check_violation then res := res || pg_temp.r('X03 unknown permissions are rejected', true); end;
  select count(distinct action) into n from public.audit_logs where action in ('earn.code_issued','earn.claimed','earn.claim_failed','redeem.requested','redeem.confirmed','redeem.confirm_failed');
  res := res || pg_temp.r('X04 all six audit event types were recorded', n=6);
  raise exception E'\n===RESULTS===\n%', res;
end $$;
